package com.example.homestay.data.dao;import androidx.room.*;import com.example.homestay.data.entity.Review;import java.util.List;@Dao public interface ReviewDao{@Query("SELECT * FROM reviews WHERE roomId=:id AND isVisible=1 ORDER BY updatedAt DESC")List<Review> getByRoomNow(long id);@Query("SELECT * FROM reviews WHERE bookingId=:id LIMIT 1")Review getByBooking(long id);@Insert(onConflict=OnConflictStrategy.ABORT)long insert(Review r);@Update void update(Review r);@Query("SELECT AVG(rating) FROM reviews WHERE roomId=:id AND isVisible=1")Double getAverage(long id);@Query("SELECT COUNT(*) FROM reviews WHERE roomId=:id AND isVisible=1")int getCount(long id);}
